package com.fiteasy.desktop

import com.fiteasy.shared.*
import com.fiteasy.shared.sync.*
import kotlinx.serialization.decodeFromString
import kotlin.test.*

class WorkoutSessionTest {
    private fun routine(vararg exercises:Exercise)=Routine(name="Test",instructions="",minutes=1,exercises=exercises.toList())
    @Test fun workoutLabelsHaveAllTenLanguages(){assertEquals(languageNames.keys,workoutRows.keys);workoutRows.forEach {(lang,row)->assertEquals(workoutKeys.size,row.split('|').size,lang);workoutKeys.forEach {assertNotNull(workoutTranslation(it,lang))}};assertEquals("Set 2/3",workoutText("Подход {0}/{1}","en",2,3))}
    @Test fun multipleSetsAndRestCountActualTime(){val r=routine(Exercise("Move",seconds=3,restSeconds=9,sets=2,setRestSeconds=1,loadKg=2.0));val s=tickWorkout(startWorkout(r,"2026-10-03"),20);assertEquals("finished",s.stage);assertEquals(7,s.elapsed);assertEquals(listOf(3,3),s.results.map {it.seconds});assertEquals(listOf(0,1),s.results.map {it.set});assertEquals(listOf(0),workoutResult(s).completed);validateWorkoutSession(s)}
    @Test fun repetitionsRequireActualConfirmation(){var s=startWorkout(routine(Exercise("Reps",seconds=2,repetitions=8,restSeconds=0)),"2026-10-03");s=tickWorkout(s,30);assertTrue(s.awaiting);assertEquals(2,s.elapsed);assertEquals(s,tickWorkout(s,10));assertFails {confirmWorkoutSet(s)};s=confirmWorkoutSet(s,5);assertEquals(5,s.results.single().repetitions);assertEquals("finished",s.stage);validateWorkoutSession(s)}
    @Test fun untimedRepetitionsDoNotAutoComplete(){var s=startWorkout(routine(Exercise("Reps",seconds=0,repetitions=8,restSeconds=0)),"2026-10-03");s=tickWorkout(s,10);assertEquals("work",s.stage);assertFalse(s.awaiting);assertTrue(s.results.isEmpty());s=confirmWorkoutSet(s,6);assertEquals(10,s.results.single().seconds);assertEquals(6,s.results.single().repetitions)}
    @Test fun skippingSetDoesNotInventCompletion(){var s=startWorkout(routine(Exercise("Move",seconds=3,restSeconds=0,sets=2,setRestSeconds=0)),"2026-10-03");s=confirmWorkoutSet(s,skip=true);s=tickWorkout(s,3);val result=workoutResult(s);assertTrue(result.completed.isEmpty());assertEquals(listOf(0),result.skipped);assertEquals(listOf(true,false),result.sets.map {it.skipped});validateWorkoutSession(s)}
    @Test fun transitionsAndMaximumAreBounded(){val r=routine(Exercise("First",seconds=1,restSeconds=2),Exercise("Second",seconds=1,restSeconds=0));assertEquals(4,tickWorkout(startWorkout(r,"2026-10-03"),20).elapsed);val s=tickWorkout(startWorkout(routine(Exercise("Manual",seconds=0,repetitions=1)),"2026-10-03"),86400);assertEquals(86400,s.elapsed);assertEquals(s,tickWorkout(s,10));assertEquals(4,startWorkout(Routine(name="Legacy",instructions="",minutes=240),"2026-10-03").routine.exercises.size)}
    @Test fun oldExerciseDefaultsAndNewContracts(){val e=codec.decodeFromString<Exercise>("""{"name":"Old","seconds":30,"repetitions":0,"restSeconds":15}""");assertEquals(1,e.sets);assertNull(e.loadKg);val data=SharedData(routines=listOf(routine(e.copy(sets=3,loadKg=2.0))));val transfer=selected(data,setOf("activity"));assertEquals(5,transfer.version);assertEquals(7,SYNC_PROTOCOL);assertEquals(data.routines,applyTransfer(SharedData(),transfer,ImportMode.MERGE,ConflictPolicy.LOCAL).routines);assertFails {applyTransfer(SharedData(),transfer.copy(version=3),ImportMode.MERGE,ConflictPolicy.LOCAL)};assertEquals(data,readBackup(prepareBackup(data,emptyList(),null,""),"").data)}
    @Test fun draftRoundtripAndEpochRejectsStaleWrite(){
        val root=java.nio.file.Files.createTempDirectory("fiteasy-workout-test-").toFile();val previous=System.getProperty("fiteasy.home");System.setProperty("fiteasy.home",root.path)
        try {val platform=DesktopPlatform();val s=tickWorkout(startWorkout(routine(Exercise("Move",seconds=30)),"2026-10-03"),5);val token=WorkoutDraftStore.token(platform);assertTrue(WorkoutDraftStore.write(platform,s,token));assertEquals(s,WorkoutDraftStore.read(platform));WorkoutDraftStore.clear(platform);assertFalse(WorkoutDraftStore.write(platform,s,token));assertNull(WorkoutDraftStore.read(platform));assertTrue(WorkoutDraftStore.write(platform,s,WorkoutDraftStore.token(platform)));platform.save(Snapshot(shared=SharedData(entries=listOf(Entry(id=s.id,type="activity",name="Saved",amount=5.0/60,unit="min",workout=workoutResult(s))))));assertNull(WorkoutDraftStore.recoverable(platform));assertNull(WorkoutDraftStore.read(platform));assertEquals("Saved",platform.load().shared.entries.single().name)}finally {if(previous==null)System.clearProperty("fiteasy.home")else System.setProperty("fiteasy.home",previous);root.deleteRecursively()}
    }
}
